/// Broken, cut short and overlong sequences, surrogates and code points past U+10FFFF are
/// refused.
#[test]
fn decode_char_refuses_malformed_sequences() {
    let refused: [&[u8]; 16] = [
        b"\x80",
        b"\xBF",
        b"\xF8\x80\x80\x80",
        b"\xFF",
        b"\xC2",
        b"\xE2\x82",
        b"\xF0\x90\x8D",
        b"\xC2\x41",
        b"\xE2\x82\x41",
        b"\xC0\x80",
        b"\xC1\xBF",
        b"\xE0\x9F\xBF",
        b"\xF0\x8F\xBF\xBF",
        b"\xED\xA0\x80",
        b"\xF4\x90\x80\x80",
        b"\xF7\xBF\xBF\xBF",
