/// character and ends at its end.
#[test]
fn decode_char_walks_a_string() {
    let s = "a\u{200C}é€𐍈.git";
    let mut rest = s.as_bytes();
    let mut chars = Vec::new();
    while !rest.is_empty() {
        let (c, len) = decode_char(rest).expect("valid");
